import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 50 New Year resolutions","description":"学习 动词后 ing 与 to do 的意义，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 50 New Year resolutions","description":"学习 动词后 ing 与 to do 的意义，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 动词后 ing 与 to do 的意义，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 49 The ideal servant","link":"/life/english/new-concept/book-3/unit-03/lesson-049"},"next":{"text":"第三册：培养技能 · Lesson 51 Predicting the future","link":"/life/english/new-concept/book-3/unit-03/lesson-051"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 49 The ideal servant","link":"/life/english/new-concept/book-3/unit-03/lesson-049"},"next":{"text":"第三册：培养技能 · Lesson 51 Predicting the future","link":"/life/english/new-concept/book-3/unit-03/lesson-051"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-050.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-050.md"}'),i={name:"life/english/new-concept/book-3/unit-03/lesson-050.md"};function r(s,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-50-new-year-resolutions" tabindex="-1">第三册：培养技能 · Lesson 50 New Year resolutions <a class="header-anchor" href="#第三册-培养技能-·-lesson-50-new-year-resolutions" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 50 New Year resolutions&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以新年目标与习惯维持为主题，训练把愿望写成可执行计划。目标应说明频率、场景和反馈方式，而不是只强调决心。学习 stop、remember、try 后接不同非谓语形式时的意义差异，尤其区分停止某动作与停下来去做另一件事。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>resolution</td><td>/ˌrezəˈluːʃən/</td><td>n.</td><td>决心</td><td>make a resolution</td></tr><tr><td>consistent</td><td>/kənˈsɪstənt/</td><td>adj.</td><td>持续一致的</td><td>consistent practice</td></tr><tr><td>progress</td><td>/ˈprəʊɡres/</td><td>n.</td><td>进步</td><td>track progress</td></tr><tr><td>routine</td><td>/ruːˈtiːn/</td><td>n.</td><td>惯例</td><td>build a routine</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>stick to — 坚持计划或规则</li><li>give up — 放弃，后接名词或动名词</li></ul><h2 id="语法讲解-动词后-ing-与-to-do-的意义" tabindex="-1">语法讲解：动词后 ing 与 to do 的意义 <a class="header-anchor" href="#语法讲解-动词后-ing-与-to-do-的意义" aria-label="Permalink to &quot;语法讲解：动词后 ing 与 to do 的意义&quot;">​</a></h2><p>stop doing 表示停止正在进行或反复进行的动作，stop to do 表示停下原来的事去做另一件事。remember doing 表示记得曾经做过，remember to do 表示记得去执行任务。try doing 强调尝试一种办法，try to do 强调努力完成。两种形式不是可以随意变化的风格选择，实际时间与目的关系会改变。写学习习惯时要先明确是回忆、提醒、停止还是试验方法，再选择结构，避免仅靠中文动词逐字套用。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I stopped checking messages during study sessions and tried leaving my phone in another room.</p></blockquote><p>我停止在学习时查看消息，并尝试把手机放到另一间屋里。</p><p>stopped checking 是终止行为；tried leaving 是试用一个办法，而非宣称最终一定成功。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>I stopped to smoke 表示停下其他事去抽烟，不能用来表达戒烟；戒烟应是 stopped smoking。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照朗读 stopped reading 与 stopped to read，给 to 一个可辨的轻音；再不用文本说明二者动作顺序。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I will read for ten minutes after breakfast. If I keep forgetting, I will try leaving the book beside my cup. At the end of the week, I will count the days I actually read.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句写一个可检验的学习习惯计划，包含试验和复盘。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>时间触发、环境提示和反馈指标完整，比抽象决心更可执行。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>翻译：记得关灯。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Remember to turn off the light.</p><p><strong>解析：</strong> 提醒执行尚需完成的动作。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>I remember closing the door 是回忆还是提醒？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 回忆。</p><p><strong>解析：</strong> remember doing 指记得已做过的事情。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>例句尝试的具体办法是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 把手机放到另一间屋里。</p><p><strong>解析：</strong> tried leaving 描述方法试验。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：动词后 ing 与 to do 的意义。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-049">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-051">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
